import {feedManifest,feedGuide,rodCSV,feedHardwareCSV} from './feed.js';
import {binarySTL,volume,zip,connectionCoupon,packedPlateMesh,hardwareSchedule,JOINT} from './geometry.js';

export function scadSource(m,kernel){
 const serial=mesh=>JSON.stringify(mesh.v.map(v=>v.map(x=>+x.toFixed(6))));
 let text='// PETAL geometry snapshot. Regenerate in PETAL after changing dimensions.\n// Parameters: '+JSON.stringify(m.p)+'\npart = "assembly"; // [assembly,'+m.parts.map(p=>p.id).join(',')+']\nprinting = true;\n';
 m.parts.forEach((p,i)=>{
  text+=`module assembly_${i}(){polyhedron(points=${serial(p.mesh)},faces=${JSON.stringify(p.mesh.f.map(f=>[...f].reverse()))},convexity=20); }\n`;
  text+=`module print_${i}(){polyhedron(points=${serial(p.output)},faces=${JSON.stringify(p.output.f.map(f=>[...f].reverse()))},convexity=20); }\n`;
  text+=`if(part=="${p.id}"){if(printing)print_${i}();else assembly_${i}();}\n`;
 });
 text+='if(part=="assembly"){\n';
 for(const inst of m.instances)text+=`rotate([0,0,${inst.a*180/Math.PI}])assembly_${m.parts.indexOf(inst.part)}();\n`;
 return text+'}\n';
}


export function manifest(m){
 const p=m.p,schedule=hardwareSchedule(m);
 return {generator:'PETAL 4.2',feed_support:feedManifest(m),units:'mm',parameters:p,interface:{revision:p.jointStyle?9:1,fastening:['front screws / rear nuts','rear screws / front hex nuts','rear screws / blind M4 inserts'][p.fastenerStyle],seat_depth_mm:p.jointStyle?JOINT.seatDepth:0,seat_clearance_per_side_mm:p.jointClearance,side_seat_radial_relief_per_side_mm:.3,nut_pocket_across_flats_mm:7+2*p.nutClearance,datum:p.rearStyle?'faceted surface with 0.05 mm axial relief':'matching tangent planes; no nominal axial clamp gap',rear_mount_bolt_circle_mm:p.jointStyle?60:40,center_opening_mm:30,hub_outer_diameter_mm:120},segmentation:{petals:m.layout.n,rings:m.layout.rows,ring_offsets_degrees:m.ringPhases.map(a=>a*180/Math.PI)},focal_length:m.focal,dish_depth:m.depth,feed_rim_half_angle_degrees:2*Math.atan(1/(4*p.fd))*180/Math.PI,assembly_bolts:m.bolts,assembly_bolts_scope:'dish shell and hub only; support hardware is separate',mount_bolts:4,heat_set_inserts:p.fastenerStyle===2?m.bolts+4:0,total_nuts:p.fastenerStyle===2?0:m.bolts+4,hardware_schedule:schedule,openscad_format:'exact mesh snapshot; change dimensions in PETAL and regenerate',perforations:{enabled:Boolean(p.perforate),diameter_mm:6,quantity:m.parts.reduce((n,x)=>n+(x.spec.perforations?.length||0)*x.qty,0)},structural_ribs:{enabled:Boolean(p.structuralRibs&&p.jointStyle),maximum_depth_mm:4,crown_width_mm:6,shoulder_width_mm:4},parts:m.parts.map(part=>({file:`${part.id}${part.supportMeshes.length?'_supported':''}_qty-${part.qty}.stl`,quantity:part.qty,dimensions_mm:part.dim,solid_volume_cm3:volume(part.mesh)/1000,support_volume_cm3:part.supportMeshes.reduce((s,x)=>s+volume(x),0)/1000,print_angle_degrees:part.angle,bed_rotation_degrees:part.bedRotation,assembly_rotations_degrees:m.instances.filter(i=>i.part===part).map(i=>i.a*180/Math.PI)})),packed_plates:m.plates.map((plate,i)=>({file:`PACKED/plate-${i+1}.stl`,placements:plate.placements.map(({part,yaw,x,y})=>({part:part.id,rotation_degrees:yaw,x_mm:x,y_mm:y}))})),notes:['Revision 9 requires a regenerated complete kit. Do not mix previous panels, plates, hubs or caps.','Geometric checks are not load, print-process or RF validation.','Mount hardware requires the external adapter stack; do not buy from an assumed mount screw length.','Use the full ASSEMBLY.md, REFLECTOR.md and INSPECTION.csv.']};
}

export function guideSections(m){
 const p=m.p,mode=p.fastenerStyle,sections=[
 {title:'Before printing',body:`PETAL 4.2 · ${p.diameter} mm · ${m.layout.n} petals × ${m.layout.rows} rings. ${p.jointStyle?'Revision 9: regenerate the entire kit. Earlier interface revisions do not match.':'Legacy straps are a comparison option; the revised locating seats and structural ribs require recessed plates.'} Start with the three FIT_TEST pieces, then one full petal and the hub. Perforations are experimental and unnecessary for the baseline test.`},
 {title:'Material and slicing',body:'ASA is the preferred outdoor starting material if your enclosed printer produces dimensionally stable parts. PCTG is useful for fit and handling prototypes; verify warm-load creep before outdoor service. ABS needs UV protection. Use dry filament and the manufacturer’s profile. A 0.4 mm nozzle, 0.2 mm layers and 4–5 walls are starting points, not a qualified process. Make hardware bosses, plates and hub bearing regions locally solid with modifiers. Keep the continuous skin fully filled; inspect the actual toolpaths.'},
 {title:'Orientation and supports',body:`${m.parts.filter(x=>x.kind==='panel').map(x=>`Ring ${x.row+1}: ${x.angle}° nominal tilt, ${x.bedRotation}° bed rotation, ${x.dim[2].toFixed(1)} mm tall`).join('. ')}. Automatic placement tries 45° first and penalizes steeper layouts; it is a fit/height heuristic, not a slicer optimization. ${p.supports?'Keep each supported STL as one multipart object with all shells in place. Breakaway ribs are sacrificial; the permanent rear ribs belong to the petal.':'Built-in supports are OFF: add suitable slicer supports and adhesion aids before printing.'} Windowed support webs use 4 mm pillars on 12 mm centers and bridges up to 8 mm; inspect their bridge toolpaths as well as root lips, hole roofs and the cap pilot. Built-in supports cover petals only. Use layer-by-layer printing, not sequential-by-object printing. Print one full petal before filling beds.`},
 {title:'Fit without forcing',body:`${p.jointStyle?`Plate seats are 2 mm deep with ${p.jointClearance.toFixed(2)} mm clearance per side. Same-ring seats have an additional 0.30 mm radial relief per side; screw clearance still limits total motion. Nut clearance is independent: pockets are ${(7+2*p.nutClearance).toFixed(2)} mm across flats. ${p.rearStyle?'Faceted backs retain 0.05 mm nominal axial relief.':'Matching flat tangent seats locate the curved-shell panels without closing an intentional axial gap.'}`:'Use matching legacy straps and check both bore positions.'} Remove burrs and elephant foot only. A plate must seat by hand with the seam open. Do not clamp a warped petal flat or use screws to pull holes into alignment. Check scale and shrinkage on a full petal if coupons fit but the ring will not close.`},
 {title:'Hardware for this mode',body:mode===2?`Rear-installed M4 screws into blind inserts. Reference: Ruthex RX-M4×8.1; ${p.insertDiameter.toFixed(2)} mm modeled bore, minimum ${p.insertDepth.toFixed(2)} mm cavity. The front remains closed with at least 2 mm skin. Install before assembly using a guided tool and depth stop. The insert’s front end stays 1 mm from the cavity roof; its rear end can be recessed below the sloped mouth. HARDWARE.csv gives the per-position recess depth for all insert positions. Do not try to make every insert flush with a sloping mouth. The schedule also gives mount-insert recess depths, independently of the unresolved adapter screw lengths. Compare face shape before and after installation. Rear heads must fit Ø8 × 2.2 mm; no washers inside these recesses.`:mode===1?'Place nominal M4 nuts (7 mm across flats, 3.2 mm tall) in the FRONT hex pockets. Bolts enter from behind; use button heads no larger than Ø8 × 2.2 mm. The pockets stop rotation but do not latch loose nuts: hold them with removable tape until screws engage. Keep tape out of bearing faces. Check full nut engagement and that screw tips stay below the reflector face. Do not add washers inside recesses.':'Bolts enter from the FRONT into rear nuts. Temporarily tape rear nuts in place, keeping tape clear of bearing faces. Cap/root screws require button heads no larger than Ø8 × 2.2 mm and no washers in the recess. Seam screw selections allow a 1 mm washer; check actual washer thickness and contact on the curved face. Stop if a washer rocks, tilts the screw or dimples the panel; the front-hex mode provides flat nut-bearing seats.'},
 {title:'Assembly without accumulated distortion',body:'Support the dish face-up on a padded cradle without flattening its parabola. Seat indexed roots in the rear hub, then place the front cap. Start all root screws loosely. Add an entire ring with the listed stagger offset, fitting rear plates loosely; do not finish one seam before the ring closes. Inspect opposite seams and the rim before tightening. Snug opposing joints in small alternating passes, then recheck the profile. Leave the designed gaps open. If a plate rocks or a seam requires force, stop and identify the mismatched or warped part. Removable rear plates avoid trapping the last petal in a closed ring of tongues.'},
 {title:'Mount and clamp load',body:`Use the ${p.jointStyle?60:40} mm mounting bolt circle and a rigid external adapter that supports the hub broadly while leaving root screws accessible. A separate prototype geared-head adapter is provided in the repository (cad/manual-aiming-mount.scad), outside this dish ZIP. ${mode===0?'At the four mounting positions, a rear backing plate needs external washers/nuts behind the adapter; do not trap nuts in the hub pockets and assume they clamp that adapter.':'Mount screws enter through the rear adapter; measure its actual bearing face and stack.'} Do not use generic steel-joint M4 torque tables. Hand-snug for the test article and stop at visible deformation. Recheck after a warm hold and assembly cycles. Inserts do not prevent creep of the surrounding plastic. Large/outdoor builds need a verified backing structure or properly designed compression limiters; this hub has no wind rating.`},
 {title:'Make it an RF reflector',body:'Bare printing plastic is not the intended RF reflector. For a first article, use thin aluminum foil tape with a specified conductive adhesive, such as 3M 1170, in narrow strips on the FRONT face. Copper tape such as 3M 1181 is an alternative but adds mass. Test adhesion on a scrap of the actual filament. Fit and measure the dish before coating; keep metal and adhesive off joint datums, nut seats, roots and bores. Coat petals individually, then bridge assembled seams with removable conductive tape. Do not tension the tape to pull seams together. The exported REFLECTOR.md covers conductive paints, finishing, continuity checks and the feed.'},
 {title:'Acceptance checks',body:'The part must fit before tightening and retain its profile after tightening. Use INSPECTION.csv for nominal front heights; check several azimuths, seam steps and rim runout, then repeat after disassembly and a warm hold. Record material, drying, orientation, slicer profile and hardware. Stop for cracks, whitening, pocket deformation, insert movement or permanent profile change. Final surface tolerance depends on operating frequency. Shape, printability, stiffness, creep and RF gain still require the test article.'}
 ];
 if(p.jointStyle){const counts=new Map(),schedule=hardwareSchedule(m);for(const r of schedule.filter(r=>r.role!=='mount'))counts.set(r.length_mm,(counts.get(r.length_mm)||0)+r.quantity);sections.splice(5,0,{title:'Nominal screw purchase list',body:[...counts].map(([length,qty])=>length?`${qty} × M4 × ${length} mm`:`${qty} screws need a custom length`).join('; ')+'. Four mount screws are additional and require the adapter dimensions. Length is measured under the head. Use HARDWARE.csv for position, allowance, washer and insert depth details. Verify against the printed coupon before buying the complete set.'});}
 if(p.structuralRibs&&p.jointStyle)sections.splice(2,0,{title:'Permanent rear structure',body:'The recommended construction keeps the selected field thickness rather than thinning it to 75%. Up to 4 mm-deep rear ribs reinforce petal boundaries and the radial centerline, with blended shoulders and clearance around joint seats. They increase CAD volume; they are intended to improve shape retention, not to establish a load rating. Do not remove these ribs as if they were supports.'});
 if(p.packPlates)sections.push({title:'Packed beds',body:'PACKED contains all required copies. Print packed beds OR the individual quantities, not both. Keep the exported arrangement. Six millimeters between bounds allows at most 3 mm brims before neighboring brims touch; slicer-generated supports can need more room. Repack in the slicer if necessary. Sequential-object toolhead clearance is not checked.'});
 if(!p.jointStyle){
  sections.find(s=>s.title==='Hardware for this mode').body='Legacy straps use M4 through bolts, washers and loose nuts. There are no front/rear captive pockets in this mode. Measure the actual grip, washer stack and nut engagement; the automatic screw schedule applies only to revision-9 plates.';
  sections.find(s=>s.title==='Assembly without accumulated distortion').body='Support the dish without flattening it. Start the legacy center clamp loosely, add the complete ring with loose straps, align opposite seams and snug gradually. Legacy straps do not provide the revised datum seats or indexed roots. Never use screw force to close a warped seam.';
 }
 if(m.feed)sections.push({title:'Rod support and optical layout',body:feedGuide(m).split('## Small parts, long metal rods')[1].split('## Assembly')[0].trim()+' Read FEED-SUPPORT.md and RODS.csv in the kit for the full setup and hardware instructions. '+m.feed.warnings.join(' ')});
 return sections;
}
export function hardwareCSV(m){
 const rows=hardwareSchedule(m),f=n=>n==null?'':Number(n).toFixed(3);
 return 'part,position,radius_mm,azimuth_degrees,role,quantity,M4_length_mm,min_length_mm,max_length_mm,washer_mm,insert_top_below_mouth_mm,status\n'+rows.map(r=>[r.part,r.position,f(r.radius_mm),f(r.azimuth_degrees),r.role,r.quantity,r.length_mm??'',f(r.min_length_mm),f(r.max_length_mm),f(r.washer_mm),f(r.insert_top_below_mouth_mm),r.role==='mount'?'MEASURE ADAPTER':r.length_mm?'VERIFY COUPON':'CUSTOM LENGTH REQUIRED'].join(',')).join('\n')+'\n';
}
export function inspectionCSV(m){
 const rows=['radius_mm,front_height_from_vertex_mm,depth_below_rim_plane_mm'];
 for(let i=0;i<=20;i++){const r=m.p.diameter*i/40,z=r*r/(4*m.focal);rows.push([r,z,m.depth-z].map(x=>x.toFixed(3)).join(','));}
 return rows.join('\n')+'\n';
}
export function guide(m){return '# PETAL 4.2 — print and assembly\n\n'+guideSections(m).map(s=>'## '+s.title+'\n\n'+s.body).join('\n\n')+'\n\n## Screw schedule\n\nHARDWARE.csv gives one row per unique hole position and the quantity across repeated parts. Radius and azimuth refer to the part in assembly orientation before its listed ring/sector rotation. Lengths are measured under the head. Seams and roots have nominal stock selections with a 0.2 mm nut-engagement / 0.4 mm insert-engagement allowance; verify the real print and hardware before buying the complete set. Blind inserts assume 8.1 mm length, at least 4 mm thread engagement and a 1 mm roof reserve plus allowance. No listed length means source/cut a suitable screw, not round upward. Mount lengths remain unresolved until the adapter is specified.\n\n## Files and offsets\n\n'+m.parts.map(p=>`- ${p.id}: ${p.qty} copies; ${p.dim.map(x=>x.toFixed(1)).join(' × ')} mm`).join('\n')+'\n\nRing offsets: '+m.ringPhases.map((a,i)=>`${i+1}: ${(a*180/Math.PI).toFixed(2)}°`).join('; ')+'.\n\npetal-snapshot.scad is an exact assembly/part mesh snapshot. Change parameters in PETAL and regenerate; this file is not an editable parametric kernel.\n';}
export function couponGuide(m){return '# Side-joint test\n\nPrint coupon-left, coupon-right and coupon-plate once each. Keep their exported orientations and add slicer supports as needed; these cropped coupons do not include built-in supports. The parts reproduce the first side joint. Try the plate without bolts first, then follow the selected hardware mode below. Check seam steps before and after snugging. These coupons do not test full-petal warping, the complete hub or a ring junction.\n\n'+guide(m);}

export function reflectorGuide(m){return `# Reflector surface and RF setup

PETAL prints a support structure. The frequency, feed, conductive finish and mount determine whether the assembled system works as an antenna. There is no measured gain or RF rating for this design.

## Recommended first article: a continuous foil face

Use a thin aluminum foil tape whose adhesive is explicitly conductive, for example 3M 1170. 3M 1181 copper foil tape is another conductive-adhesive option, but copper adds more mass. These are examples of material construction, not qualified PETAL finishes or outdoor lifetime guarantees. Ordinary HVAC tape may have insulating adhesive; overlapping it does not guarantee electrical contact between strips.

Sources: https://www.3m.com/3M/en_US/p/d/b5005158003/ and https://www.3m.com/3M/en_US/p/d/b5005158005/

1. Print an adhesion/coating scrap from the actual filament. Check the tape and any primer after a warm hold and gentle peel. Do not assume adhesion to an injection-molded plastic transfers to a printed surface.
2. Dry-fit, mark and measure the uncoated assembly. Complete heat-setting before applying the conductive finish. Lightly remove burrs; do not sand the parabola into a different shape.
3. Apply narrow strips to each front petal, burnishing gently from the center outward. Start around 10–20 mm strip width and reduce it where compound curvature causes wrinkles. Avoid stretching foil tight across gaps or unsupported holes. Keep overlaps small and consistent; record their height if operating at short wavelengths.
4. Mask root grooves, plate seats, bearing faces and bores. Cover the front cap with the same finish, preserving access to hardware. Do not bridge a pocket with foil that a screw will tear during service.
5. Assemble and align first. Bridge seams with removable strips afterward, without pulling petals together. Remove these strips before disassembly. Do not use a continuous skin as an alignment clamp.
6. With power disconnected, check foil-to-foil continuity across strips, cap and seams at many points. Compare against the meter’s shorted-lead baseline; intermittent or unexpectedly high resistance needs investigation. DC continuity is a useful workmanship check, not proof of RF efficiency.
7. Recheck surface shape, adhesion and continuity after thermal cycling and repeated assembly. Corrosion, water ingress and differential expansion require an outdoor finishing plan. Do not assume a generic clearcoat is RF-neutral or compatible with the tape. Keep a specular foil-covered dish pointed away from the Sun during handling; concentrated sunlight near the focus can heat the feed or fixture.

## Conductive paints

A specified silver or silver-coated-copper conductive coating is an alternative when foil wrinkles are unacceptable. Examples are MG Chemicals 842AR and 843AR. They are designed as conductive shielding coatings; that does not establish antenna-reflector performance on PETAL. Follow the current technical data and safety sheets, verify dry-film thickness and sheet resistance, and test solvent/primer compatibility on the actual ASA, ABS or PCTG print. Solvent attack, shrinkage and poor adhesion can ruin surface accuracy. Metallic-looking craft paint, ordinary graphite paint and carbon-filled filament are not automatically suitable low-loss reflectors.

Sources: https://mgchemicals.com/products/conductive-paint/conductive-acrylic-paints/silver-conductive-paint/ and https://mgchemicals.com/products/conductive-paint/conductive-acrylic-paint/copper-conductive-paint/

## Perforations and mesh

Keep perforations off for the baseline article. Conductive mesh must be chosen for the intended wavelength; openings, wire size, conductivity and surface accuracy all matter. Do not equate percent open area with gain loss. A continuous foil covering over printed holes needs support against sagging and will largely block airflow. Reference: https://www.gmrt.ncra.tifr.res.in/doc/WEBLF/LFRA/node173.html

## Feed and alignment

This configuration has focal length ${m.focal.toFixed(2)} mm from the parabola vertex, dish depth ${m.depth.toFixed(2)} mm, and rim half-angle ${(2*Math.atan(1/(4*m.p.fd))*180/Math.PI).toFixed(2)} degrees as seen from the focus. The vertex is the extrapolated center of the parabola, not the rear hub surface or rim plane. Place the feed phase center at the focus and match its illumination to that rim angle. Provide rigid, adjustable axial/lateral positioning and polarization adjustment. Route and strain-relieve the cable so it cannot move the feed. ${m.feed?'Support parts and rod cuts are included; see FEED-SUPPORT.md. The RF feed and its specific adapter remain separate.':'Enable the optional rod support to generate mounting parts and rod cuts. The RF feed is not supplied.'}

Choose an operating band before setting surface tolerances. As an engineering starting budget, allocate no more than wavelength/50 RMS to structural/assembly error, then account separately for finish, feed and pointing. This is a proposed test criterion, not a verified capability. Use the shortest wavelength in a band. Measure at several azimuths and elevations; systematic seam steps and defocus need attention beyond a single RMS number.

Check feed return loss if equipment is available, but also compare received level and beam pattern against a known reference with fixed polarization, cable, receiver gain and geometry. Good impedance matching alone does not prove reflector gain. Use a suitable far-field range or a properly characterized near-field method, rather than a nearby transmitter of unknown geometry. RF background: https://www.cv.nrao.edu/~sransom/web/Ch3.html

## Material references

ASA: outdoor UV/temperature suitability, with significant warping risk unless the printer environment is controlled: https://help.prusa3d.com/article/asa_1809
PCTG: manufacturer-specific material data; heat-distortion temperature is not a continuous precision-service limit: https://fiberlogy.com/en/fiberlogy-filaments/pctg/
Inserts and plastic creep: https://www.spirol.com/resources/white-papers/how-to-properly-mate-compression-limiters-and-threaded-inserts-in-plastic-assemblies/
`;}
export function kit(m,kernel){
 const coupons=connectionCoupon(m);
 return zip([...m.plates.map((plate,i)=>({name:`PACKED/plate-${i+1}.stl`,data:binarySTL(packedPlateMesh(plate))})),...coupons.map(p=>({name:`FIT_TEST/${p.id}.stl`,data:binarySTL(p.output)})),...(coupons.length?[{name:'FIT_TEST/README.md',data:couponGuide(m)}]:[]),...m.parts.map(p=>({name:`STL/${p.id}${p.supportMeshes.length?'_supported':''}_qty-${p.qty}.stl`,data:binarySTL(p.output)})),{name:'petal-snapshot.scad',data:scadSource(m,kernel)},{name:'parameters.json',data:JSON.stringify(manifest(m),null,2)},{name:'ASSEMBLY.md',data:guide(m)},{name:'REFLECTOR.md',data:reflectorGuide(m)},{name:'HARDWARE.csv',data:hardwareCSV(m)},{name:'INSPECTION.csv',data:inspectionCSV(m)},...(m.feed?[{name:'FEED-SUPPORT.md',data:feedGuide(m)},{name:'RODS.csv',data:rodCSV(m)},{name:'FEED-HARDWARE.csv',data:feedHardwareCSV(m)}]:[])]);
}
